    String id = json(response).path("id").asString();
    assertThat(queryLong("SELECT count(*) FROM registration WHERE id = ?", UUID.fromString(id)))
        .isEqualTo(1);
    assertThat(JSON_COPY_DIR.resolve(id + ".json")).exists();
  }
}
