import { fetchFormConfig, submitRegistration } from "./api";
import type { RegistrationRequest } from "./types";

const request: RegistrationRequest = {
  type: "EXTERNAL",
  firstName: "Ana",
  lastName: "Novak",
  email: "ana@example.org",
  organization: "I",
  optionIds: [],
  consents: ["privacy"],
  recaptchaToken: "t",
};

